cat > probe_getauth_test.go <<'EOF'
package main

import (
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

func TestProbeGetAuth(t *testing.T) {
	store := NewStore(time.Minute)
	store.Create("s1", "alice")
	handler := sessionHandler(store)

	// Missing token: 401.
	rec := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/session?id=s1", nil)
	handler(rec, req)
	if rec.Code != http.StatusUnauthorized {
		t.Fatalf("no token status = %d, want 401", rec.Code)
	}

	// Wrong token: 401.
	rec = httptest.NewRecorder()
	req = httptest.NewRequest("GET", "/session?id=s1", nil)
	req.Header.Set("X-Session-Token", "wrong")
	handler(rec, req)
	if rec.Code != http.StatusUnauthorized {
		t.Fatalf("wrong token status = %d, want 401", rec.Code)
	}

	// Correct token: 200.
	rec = httptest.NewRecorder()
	req = httptest.NewRequest("GET", "/session?id=s1", nil)
	req.Header.Set("X-Session-Token", validToken)
	handler(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("valid token status = %d, want 200", rec.Code)
	}

	// POST stays open.
	rec = httptest.NewRecorder()
	req = httptest.NewRequest("POST", "/session?id=s2&user=bob", nil)
	req.Header.Set("Content-Type", "application/json")
	handler(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("POST with no token status = %d, want 200", rec.Code)
	}

}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_getauth_test.go

# Structural: constant-time comparison required (no direct == on secrets).
src=$(cat main.go)
echo "$src" | grep -q "subtle.ConstantTimeCompare" || { echo "token comparison must use subtle.ConstantTimeCompare"; exit 1; }
exit $rc

